const allExpenses = $('Get All Expenses').all().map(i => i.json);
const objects = $('Get All Objects').all().map(i => i.json);

// Только confirmed
const confirmed = allExpenses.filter(e => e.status === 'confirmed');

// За последние 7 дней
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const thisWeek = confirmed.filter(e => {
  const d = new Date(e.date);
  return d >= weekAgo && d <= now;
});

// Сводка по категориям
const byCat = {};
thisWeek.forEach(e => {
  const cat = e.category || 'other';
  byCat[cat] = (byCat[cat] || 0) + Number(e.amount || 0);
});

// Сводка по объектам
const byObj = {};
thisWeek.forEach(e => {
  const obj = e.object_name || 'Не указан';
  byObj[obj] = (byObj[obj] || 0) + Number(e.amount || 0);
});

// Бюджеты объектов
const budgets = {};
const totalByObj = {};
objects.forEach(o => {
  budgets[o.object_id] = { name: o.object_name, budget: Number(o.budget || 0) };
});
confirmed.forEach(e => {
  if (e.object_id) {
    totalByObj[e.object_id] = (totalByObj[e.object_id] || 0) + Number(e.amount || 0);
  }
});

const budgetStatus = Object.keys(budgets).map(id => ({
  object: budgets[id].name,
  budget: budgets[id].budget,
  spent: totalByObj[id] || 0,
  pct: budgets[id].budget > 0 ? Math.round((totalByObj[id] || 0) / budgets[id].budget * 100) : 0
}));

// Данные для промпта
const data = {
  period: `${weekAgo.toISOString().slice(0,10)} — ${now.toISOString().slice(0,10)}`,
  total_this_week: thisWeek.reduce((s, e) => s + Number(e.amount || 0), 0),
  expenses_count: thisWeek.length,
  by_category: byCat,
  by_object: byObj,
  budget_status: budgetStatus,
  all_expenses_this_week: thisWeek.map(e => ({
    date: e.date,
    amount: e.amount,
    category: e.category,
    object: e.object_name,
    description: e.description,
    who: e.submitted_by
  }))
};

const prompt = `Ты — финансовый аналитик строительной бригады.
Вот данные за неделю. Напиши краткий аналитический отчёт на русском языке для руководителя бригады.

Данные:
${JSON.stringify(data, null, 2)}

Структура отчёта:
1. Итого за неделю (сумма, количество чеков)
2. Расходы по категориям (топ категории, доли)
3. Расходы по объектам
4. Статус бюджетов (какой процент израсходован по каждому объекту)
5. Аномалии или наблюдения (необычно крупные траты, рост расходов, объекты близкие к лимиту)
6. Рекомендации (1-2 коротких совета)

Формат: текст для Telegram, используй эмодзи для структуры. Не используй markdown-форматирование (*жирный* и т.п.), только простой текст с эмодзи. Максимум 2000 символов.`;

const request_body = JSON.stringify({
  model: "deepseek-v4-flash",
  messages: [
    { role: "user", content: prompt }
  ],
  temperature: 0.3,
  max_tokens: 2000
});

return [{ json: { request_body } }];

